import React from 'react'
import Banner from '../../components/Banner/Banner'
import Advantages from '../../components/Advantages/Advantages'

const Home = () => {
  const advantagesData = {
    title: 'Наши преимущества - Страница 1',
    imageUrl: '/img/Advantages.png',
    content: [
      'Продакшн артистов любого уровня',
      'Наши работы на радио и в популярных плейлистах',
      'Топовое оборудование и лицензионный софт',
      'Работа в любых жанрах'
    ],
  };

  return (
    <div>
      <Banner />
      <Advantages
        title={advantagesData.title}
        imageUrl={advantagesData.imageUrl}
        content={advantagesData.content}
      />
    </div>
  )
}

export default Home
